        return false;
    }

    pm->user_data = s_live_map;
    /* splash 仍盖着：所有 LiveMap 定时器保持暂停，只准备文件资源。 */
    s_live_map->covered = true;

    s_boot_deferred = false;
    s_boot_files_ready = false;
    LV_LOG_INFO("map boot: resources created");
    return true;
}

