{
    uint32_t rev = 0;

    if (!page) {
        return;
    }

    rev = page->map ? vmap_view_render_revision(page->map) : 0u;

    page->covered = false;
    if (page->map && page->map_ui_visible) {
        lv_obj_t * canvas = vmap_view_get_obj(page->map);

        /* 保留大画布；下一 GNSS 拍按位移阈值 catchup，不因关闭 cover 重载。 */
